    }
  },
  "signal_basis": {
    "component_id": "C031_signal_basis",
    "value": "Using queue-entry-to-upload-completion timing, an export remains running after more than one hour has elapsed.",
    "scope": "The elapsed time exceeds one hour; an export stopped before that point has an unknown threshold outcome.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
